USE master;
GO
IF DB_ID(N'KaluzDB_Final') IS NULL CREATE DATABASE KaluzDB_Final;
GO
USE KaluzDB_Final;
GO
IF OBJECT_ID('dbo.Rol','U') IS NULL CREATE TABLE Rol(IdRol INT IDENTITY PRIMARY KEY,Nombre NVARCHAR(30) NOT NULL UNIQUE,Descripcion NVARCHAR(150));
IF OBJECT_ID('dbo.Usuario','U') IS NULL CREATE TABLE Usuario(IdUsuario INT IDENTITY PRIMARY KEY,IdRol INT NOT NULL REFERENCES Rol(IdRol),NombreCompleto NVARCHAR(100) NOT NULL,Email NVARCHAR(120) NOT NULL UNIQUE,PasswordHash NVARCHAR(255) NOT NULL,Activo BIT NOT NULL DEFAULT 1,FechaCreacion DATETIME2 NOT NULL DEFAULT SYSDATETIME(),UltimoAcceso DATETIME2 NULL);
IF OBJECT_ID('dbo.Categoria','U') IS NULL CREATE TABLE Categoria(IdCategoria INT IDENTITY PRIMARY KEY,Nombre NVARCHAR(60) NOT NULL UNIQUE,Activo BIT NOT NULL DEFAULT 1);
IF OBJECT_ID('dbo.Producto','U') IS NULL CREATE TABLE Producto(IdProducto INT IDENTITY PRIMARY KEY,Codigo NVARCHAR(20) NOT NULL UNIQUE,Nombre NVARCHAR(120) NOT NULL,Descripcion NVARCHAR(500),IdCategoria INT NOT NULL REFERENCES Categoria(IdCategoria),Marca NVARCHAR(60),PrecioCosto DECIMAL(10,2) NOT NULL CHECK(PrecioCosto>=0),PrecioVenta DECIMAL(10,2) NOT NULL CHECK(PrecioVenta>0),Foto NVARCHAR(255),Activo BIT NOT NULL DEFAULT 1,FechaCreacion DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('dbo.ProductoVariante','U') IS NULL CREATE TABLE ProductoVariante(IdVariante INT IDENTITY PRIMARY KEY,IdProducto INT NOT NULL REFERENCES Producto(IdProducto),Talla NVARCHAR(10) NOT NULL,Color NVARCHAR(30) NOT NULL,SKU NVARCHAR(40) NOT NULL UNIQUE,StockActual INT NOT NULL DEFAULT 0 CHECK(StockActual>=0),StockMinimo INT NOT NULL DEFAULT 2 CHECK(StockMinimo>=0),Activo BIT NOT NULL DEFAULT 1,CONSTRAINT UQ_Variante_TallaColor UNIQUE(IdProducto,Talla,Color));
IF OBJECT_ID('dbo.MovimientoInventario','U') IS NULL CREATE TABLE MovimientoInventario(IdMovimiento INT IDENTITY PRIMARY KEY,IdVariante INT NOT NULL REFERENCES ProductoVariante(IdVariante),Tipo NVARCHAR(12) NOT NULL CHECK(Tipo IN('Entrada','Salida','Ajuste','Devolucion')),Cantidad INT NOT NULL CHECK(Cantidad<>0),StockResultante INT NOT NULL CHECK(StockResultante>=0),Fecha DATETIME2 NOT NULL DEFAULT SYSDATETIME(),Motivo NVARCHAR(200),Referencia NVARCHAR(40),IdUsuario INT NOT NULL REFERENCES Usuario(IdUsuario));
IF OBJECT_ID('dbo.Cliente','U') IS NULL CREATE TABLE Cliente(IdCliente INT IDENTITY PRIMARY KEY,Nombres NVARCHAR(80) NOT NULL,Apellidos NVARCHAR(80),DNI NVARCHAR(12),Telefono NVARCHAR(20),Email NVARCHAR(120),FechaNacimiento DATE,Notas NVARCHAR(500),Activo BIT NOT NULL DEFAULT 1,FechaRegistro DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_Cliente_DNI' AND object_id=OBJECT_ID('dbo.Cliente')) CREATE UNIQUE INDEX UX_Cliente_DNI ON Cliente(DNI) WHERE DNI IS NOT NULL;
IF OBJECT_ID('dbo.MetodoPago','U') IS NULL CREATE TABLE MetodoPago(IdMetodoPago INT IDENTITY PRIMARY KEY,Nombre NVARCHAR(30) NOT NULL UNIQUE);
IF OBJECT_ID('dbo.Caja','U') IS NULL CREATE TABLE Caja(IdCaja INT IDENTITY PRIMARY KEY,IdUsuario INT NOT NULL REFERENCES Usuario(IdUsuario),FechaApertura DATETIME2 NOT NULL DEFAULT SYSDATETIME(),MontoInicial DECIMAL(10,2) NOT NULL CHECK(MontoInicial>=0),FechaCierre DATETIME2,MontoEsperado DECIMAL(10,2),MontoFinal DECIMAL(10,2),Diferencia DECIMAL(10,2),Estado NVARCHAR(10) NOT NULL DEFAULT 'Abierta' CHECK(Estado IN('Abierta','Cerrada')));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_Caja_Abierta' AND object_id=OBJECT_ID('dbo.Caja')) CREATE UNIQUE INDEX UX_Caja_Abierta ON Caja(IdUsuario) WHERE Estado='Abierta';
IF OBJECT_ID('dbo.MovimientoCaja','U') IS NULL CREATE TABLE MovimientoCaja(IdMovimientoCaja INT IDENTITY PRIMARY KEY,IdCaja INT NOT NULL REFERENCES Caja(IdCaja),Tipo NVARCHAR(10) NOT NULL CHECK(Tipo IN('Ingreso','Egreso')),Concepto NVARCHAR(150) NOT NULL,Monto DECIMAL(10,2) NOT NULL CHECK(Monto>0),Fecha DATETIME2 NOT NULL DEFAULT SYSDATETIME(),Referencia NVARCHAR(40),IdMetodoPago INT NOT NULL REFERENCES MetodoPago(IdMetodoPago));
IF OBJECT_ID('dbo.Venta','U') IS NULL CREATE TABLE Venta(IdVenta INT IDENTITY PRIMARY KEY,NumeroTicket NVARCHAR(45) NOT NULL UNIQUE,Fecha DATETIME2 NOT NULL DEFAULT SYSDATETIME(),IdCliente INT NULL REFERENCES Cliente(IdCliente),IdUsuario INT NOT NULL REFERENCES Usuario(IdUsuario),IdCaja INT NOT NULL REFERENCES Caja(IdCaja),IdMetodoPago INT NOT NULL REFERENCES MetodoPago(IdMetodoPago),Subtotal DECIMAL(10,2) NOT NULL CHECK(Subtotal>=0),Descuento DECIMAL(10,2) NOT NULL DEFAULT 0 CHECK(Descuento>=0),Total DECIMAL(10,2) NOT NULL CHECK(Total>=0),Estado NVARCHAR(12) NOT NULL DEFAULT 'Completada' CHECK(Estado IN('Completada','Anulada')),MotivoAnulacion NVARCHAR(200),CONSTRAINT CK_Venta_TotalConsistente CHECK(Total=Subtotal-Descuento));
IF OBJECT_ID('dbo.DetalleVenta','U') IS NULL CREATE TABLE DetalleVenta(IdDetalleVenta INT IDENTITY PRIMARY KEY,IdVenta INT NOT NULL REFERENCES Venta(IdVenta),IdVariante INT NOT NULL REFERENCES ProductoVariante(IdVariante),Cantidad INT NOT NULL CHECK(Cantidad>0),PrecioUnitario DECIMAL(10,2) NOT NULL CHECK(PrecioUnitario>=0),Subtotal DECIMAL(10,2) NOT NULL,CONSTRAINT CK_DetVenta_Subtotal CHECK(Subtotal=CONVERT(DECIMAL(10,2),Cantidad*PrecioUnitario)));
IF OBJECT_ID('dbo.Devolucion','U') IS NULL CREATE TABLE Devolucion(IdDevolucion INT IDENTITY PRIMARY KEY,IdVenta INT NOT NULL REFERENCES Venta(IdVenta),IdUsuario INT NOT NULL REFERENCES Usuario(IdUsuario),Fecha DATETIME2 NOT NULL DEFAULT SYSDATETIME(),Tipo NVARCHAR(12) NOT NULL CHECK(Tipo IN('Devolucion','Cambio')),Motivo NVARCHAR(200),MontoReembolso DECIMAL(10,2) NOT NULL DEFAULT 0 CHECK(MontoReembolso>=0),DiferenciaCobrada DECIMAL(10,2) NOT NULL DEFAULT 0);
IF OBJECT_ID('dbo.DetalleDevolucion','U') IS NULL CREATE TABLE DetalleDevolucion(IdDetalleDevolucion INT IDENTITY PRIMARY KEY,IdDevolucion INT NOT NULL REFERENCES Devolucion(IdDevolucion),IdDetalleVenta INT NOT NULL REFERENCES DetalleVenta(IdDetalleVenta),Cantidad INT NOT NULL CHECK(Cantidad>0),IdVarianteCambio INT NULL REFERENCES ProductoVariante(IdVariante),CantidadCambio INT NULL CHECK(CantidadCambio IS NULL OR CantidadCambio>0));
IF OBJECT_ID('dbo.Proveedor','U') IS NULL CREATE TABLE Proveedor(IdProveedor INT IDENTITY PRIMARY KEY,Nombre NVARCHAR(120) NOT NULL,RUC NVARCHAR(11),Contacto NVARCHAR(80),Telefono NVARCHAR(20),Email NVARCHAR(120),Direccion NVARCHAR(200),Activo BIT NOT NULL DEFAULT 1);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_Proveedor_RUC' AND object_id=OBJECT_ID('dbo.Proveedor')) CREATE UNIQUE INDEX UX_Proveedor_RUC ON Proveedor(RUC) WHERE RUC IS NOT NULL;
IF OBJECT_ID('dbo.Compra','U') IS NULL CREATE TABLE Compra(IdCompra INT IDENTITY PRIMARY KEY,IdProveedor INT NOT NULL REFERENCES Proveedor(IdProveedor),IdUsuario INT NOT NULL REFERENCES Usuario(IdUsuario),Fecha DATETIME2 NOT NULL DEFAULT SYSDATETIME(),NumeroDocumento NVARCHAR(30),Total DECIMAL(10,2) NOT NULL CHECK(Total>=0),Estado NVARCHAR(10) NOT NULL DEFAULT 'Pendiente' CHECK(Estado IN('Pendiente','Parcial','Recibida','Anulada')));
IF OBJECT_ID('dbo.DetalleCompra','U') IS NULL CREATE TABLE DetalleCompra(IdDetalleCompra INT IDENTITY PRIMARY KEY,IdCompra INT NOT NULL REFERENCES Compra(IdCompra),IdVariante INT NOT NULL REFERENCES ProductoVariante(IdVariante),Cantidad INT NOT NULL CHECK(Cantidad>0),CantidadRecibida INT NOT NULL DEFAULT 0, CostoUnitario DECIMAL(10,2) NOT NULL CHECK(CostoUnitario>=0),Subtotal DECIMAL(10,2) NOT NULL,CONSTRAINT CK_DetCompra_Recibida CHECK(CantidadRecibida BETWEEN 0 AND Cantidad),CONSTRAINT CK_DetCompra_Subtotal CHECK(Subtotal=CONVERT(DECIMAL(10,2),Cantidad*CostoUnitario)));
IF OBJECT_ID('dbo.CategoriaGasto','U') IS NULL CREATE TABLE CategoriaGasto(IdCategoriaGasto INT IDENTITY PRIMARY KEY,Nombre NVARCHAR(50) NOT NULL UNIQUE);
IF OBJECT_ID('dbo.Gasto','U') IS NULL CREATE TABLE Gasto(IdGasto INT IDENTITY PRIMARY KEY,IdCategoriaGasto INT NOT NULL REFERENCES CategoriaGasto(IdCategoriaGasto),IdUsuario INT NOT NULL REFERENCES Usuario(IdUsuario),Fecha DATE NOT NULL DEFAULT CONVERT(date,SYSDATETIME()),Concepto NVARCHAR(150) NOT NULL,Monto DECIMAL(10,2) NOT NULL CHECK(Monto>0));
IF OBJECT_ID('dbo.Auditoria','U') IS NULL CREATE TABLE Auditoria(IdAuditoria INT IDENTITY PRIMARY KEY,IdUsuario INT NOT NULL REFERENCES Usuario(IdUsuario),Fecha DATETIME2 NOT NULL DEFAULT SYSDATETIME(),Accion NVARCHAR(40) NOT NULL,Entidad NVARCHAR(40) NOT NULL,IdRegistro INT,Detalle NVARCHAR(500));
GO
IF NOT EXISTS(SELECT 1 FROM Rol WHERE Nombre='Administrador') INSERT Rol(Nombre,Descripcion) VALUES('Administrador','Acceso total a la aplicación');
IF NOT EXISTS(SELECT 1 FROM Rol WHERE Nombre='Vendedora') INSERT Rol(Nombre,Descripcion) VALUES('Vendedora','Ventas, caja, clientes, devoluciones y consulta de stock');
INSERT MetodoPago(Nombre) SELECT x.Nombre FROM (VALUES('Efectivo'),('Tarjeta'),('Yape'),('Plin'),('Transferencia'))x(Nombre) WHERE NOT EXISTS(SELECT 1 FROM MetodoPago m WHERE m.Nombre=x.Nombre);
INSERT Categoria(Nombre) SELECT x.Nombre FROM (VALUES('Blusas'),('Vestidos'),('Pantalones'),('Faldas'),('Casacas'),('Accesorios'))x(Nombre) WHERE NOT EXISTS(SELECT 1 FROM Categoria c WHERE c.Nombre=x.Nombre);
INSERT CategoriaGasto(Nombre) SELECT x.Nombre FROM (VALUES('Alquiler'),('Servicios'),('Sueldos'),('Publicidad'),('Otros'))x(Nombre) WHERE NOT EXISTS(SELECT 1 FROM CategoriaGasto c WHERE c.Nombre=x.Nombre);
GO
CREATE OR ALTER VIEW dbo.vw_StockBajo AS SELECT v.IdVariante,p.Codigo,p.Nombre,v.Talla,v.Color,v.SKU,v.StockActual,v.StockMinimo FROM dbo.ProductoVariante v JOIN dbo.Producto p ON p.IdProducto=v.IdProducto WHERE v.Activo=1 AND p.Activo=1 AND v.StockActual<=v.StockMinimo;
GO
CREATE OR ALTER VIEW dbo.vw_Ventas30Dias AS SELECT CONVERT(date,Fecha) AS Dia,COUNT(*) AS Cantidad,SUM(Total) AS Total FROM dbo.Venta WHERE Estado='Completada' AND Fecha>=DATEADD(day,-30,SYSDATETIME()) GROUP BY CONVERT(date,Fecha);
GO
CREATE OR ALTER VIEW dbo.vw_InventarioValorizado AS SELECT p.Codigo,p.Nombre,v.SKU,v.Talla,v.Color,v.StockActual,p.PrecioCosto,CAST(v.StockActual*p.PrecioCosto AS decimal(18,2)) AS Valorizacion FROM dbo.ProductoVariante v JOIN dbo.Producto p ON p.IdProducto=v.IdProducto;
GO
PRINT 'KaluzDB_Final está preparada. Visita /Account/Setup para crear el primer administrador.';

